import json, sys
RECORDS = {1: {"id":1,"account":"alice","value":"private"}, 2:{"id":2,"account":"bob","value":"other"}}
def read_record(account, record_id):
    record = RECORDS[record_id]
    if record["account"] != account:
        raise PermissionError("Record not accessible")
    return record

if __name__ == '__main__':
    try:
        record = read_record(sys.argv[1], int(sys.argv[2]))
    except (KeyError, PermissionError):
        sys.exit("Record not accessible")
    print(json.dumps(record))

